import { Component, forwardRef, input } from '@angular/core';
import { FormsModule, NG_VALUE_ACCESSOR } from '@angular/forms';
import { NzSelectModule } from 'ng-zorro-antd/select';
import { HrmControl } from '../shared/hrm-control';
import { HrmOption, HrmOptionGroup } from '../shared/hrm-option';
import { HrmSize, HrmStatus, toNzStatus } from './hrm-input';

const toNz = (s: HrmSize) => (s === 'sm' ? 'small' : s === 'lg' ? 'large' : 'default');

/** hrm-select — CVA, options-driven, single/multiple, search/clear/status.
 *  Danh sách phẳng: [options]. Danh sách phân nhóm: [groups] (mỗi nhóm có nhãn + options). */
@Component({
  selector: 'hrm-select',
  imports: [FormsModule, NzSelectModule],
  template: `
    <nz-select
      style="width:100%"
      [ngModel]="value()"
      (ngModelChange)="emit($event)"
      (nzBlur)="markTouched()"
      [nzMode]="multiple() ? 'multiple' : 'default'"
      [nzPlaceHolder]="placeholder()"
      [nzAllowClear]="allowClear()"
      [nzShowSearch]="showSearch()"
      [nzDisabled]="disabled()"
      [nzSize]="toNz(size())"
      [nzStatus]="toNzStatus(status())">
      @if (groups().length) {
        @for (g of groups(); track g.label) {
          <nz-option-group [nzLabel]="g.label">
            @for (o of g.options; track o.value) {
              <nz-option [nzValue]="o.value" [nzLabel]="o.label" [nzDisabled]="o.disabled ?? false"></nz-option>
            }
          </nz-option-group>
        }
      } @else {
        @for (o of options(); track o.value) {
          <nz-option [nzValue]="o.value" [nzLabel]="o.label" [nzDisabled]="o.disabled ?? false"></nz-option>
        }
      }
    </nz-select>
  `,
  host: { class: 'hrm-select', '[class.hrm-status-success]': "status() === 'success'" },
  providers: [{ provide: NG_VALUE_ACCESSOR, useExisting: forwardRef(() => HrmSelect), multi: true }],
})
export class HrmSelect extends HrmControl<unknown> {
  readonly options = input<HrmOption[]>([]);
  readonly groups = input<HrmOptionGroup[]>([]);
  readonly placeholder = input('');
  readonly multiple = input(false);
  readonly allowClear = input(true);
  readonly showSearch = input(true);
  readonly size = input<HrmSize>('md');
  readonly status = input<HrmStatus>('');
  protected readonly toNz = toNz;
  protected readonly toNzStatus = toNzStatus;
}
